+      while (currentWeekStart.isBefore(monthEnd) || currentWeekStart.month == now.month) {
+        final weekStartStr = '${currentWeekStart.year}-${currentWeekStart.month.toString().padLeft(2, '0')}-${currentWeekStart.day.toString().padLeft(2, '0')}';
