+                    final period = timeMatch.group(3)?.toLowerCase();
+                    
+                    if (period != null) {
+                      // AM/PM Format
+                      if (period == 'pm' && hour != 12) {
+                        hour += 12;
+                      } else if (period == 'am' && hour == 12) {
+                        hour = 0;
