+  Future<String> _queryKitsu(String searchName) async {
+    try {
+      // Kitsu API - Text Suche
+      final encodedSearch = Uri.encodeComponent(searchName);
+      final url = 'https://kitsu.io/api/edge/anime?filter[text]=$encodedSearch&page[limit]=1';
+      
+      final response = await http.get(
+        Uri.parse(url),
+        headers: {
+          'Accept': 'application/vnd.api+json',
+          'Content-Type': 'application/vnd.api+json',
+        },
+      );
+      
+      if (response.statusCode == 200) {
+        // Parse JSON Response - suche nach posterImage
+        final body = response.body;
+        
+        // Versuche original Poster zu finden
+        var imageMatch = RegExp(r'"posterImage":\s*\{[^}]*"large":\s*"([^"]+)"').firstMatch(body);
+        if (imageMatch != null) {
+          final imageUrl = imageMatch.group(1)!.replaceAll(r'\/', '/');
+          return imageUrl;
+        }
+        
+        // Fallback zu medium
+        imageMatch = RegExp(r'"posterImage":\s*\{[^}]*"medium":\s*"([^"]+)"').firstMatch(body);
+        if (imageMatch != null) {
+          final imageUrl = imageMatch.group(1)!.replaceAll(r'\/', '/');
+          return imageUrl;
+        }
+        
+        // Fallback zu original
+        imageMatch = RegExp(r'"posterImage":\s*\{[^}]*"original":\s*"([^"]+)"').firstMatch(body);
+        if (imageMatch != null) {
+          final imageUrl = imageMatch.group(1)!.replaceAll(r'\/', '/');
+          return imageUrl;
+        }
+      }
+    } catch (e) {
+      // Fehler ignorieren
+    }
+    return '';
+  }
