-  /// Findet eine gecachte Bild-URL für einen Anime-Titel
-  String? _findCachedImageUrl(String title) {
-    // Versuche exakten Match
-    if (_imageCache.containsKey(title)) {
-      print('  📦 Cache exact match: $title');
-      return _imageCache[title];
-    }
-    
-    // Bereinige den Namen auf DIE GLEICHE WEISE wie in _fetchImageFromKitsu()
-    var cleanedName = _cleanAnimeName(title);
-    cleanedName = cleanedName.replaceAll(RegExp(r'[^\w\s\-]'), ' ').replaceAll(RegExp(r'\s+'), ' ').trim();
-    
-    if (_imageCache.containsKey(cleanedName)) {
-      print('  📦 Cache cleaned match: $title -> $cleanedName');
-      return _imageCache[cleanedName];
-    }
-    
-    // Versuche erste 3 Wörter
-    final words = cleanedName.split(' ');
-    if (words.length > 3) {
-      final shortName = words.take(3).join(' ');
-      if (_imageCache.containsKey(shortName)) {
-        print('  📦 Cache 3-word match: $title -> $shortName');
-        return _imageCache[shortName];
-      }
-    }
-    
-    // Versuche erste 2 Wörter
-    if (words.length > 2) {
-      final shortName = words.take(2).join(' ');
-      if (_imageCache.containsKey(shortName)) {
-        print('  📦 Cache 2-word match: $title -> $shortName');
-        return _imageCache[shortName];
-      }
-    }
-    
-    // Kein Match - zeige gecachte Namen zum Debuggen
-    if (_imageCache.isNotEmpty) {
-      final similarKeys = _imageCache.keys.where((key) => 
-        key.toLowerCase().contains(cleanedName.toLowerCase().split(' ').first.toLowerCase()) ||
-        cleanedName.toLowerCase().contains(key.toLowerCase().split(' ').first.toLowerCase())
-      ).toList();
-      
-      if (similarKeys.isNotEmpty) {
-        print('  ⚠ No exact match for "$title" (cleaned: "$cleanedName"), but found similar cached: ${similarKeys.join(", ")}');
-      }
-    }
-    
-    return null;
-  }
