+    // Versuche erste 2 Wörter
+    if (words.length > 2) {
+      final shortName = words.take(2).join(' ');
+      if (_imageCache.containsKey(shortName)) {
+        print('  📦 Cache 2-word match: $title -> $shortName');
+        return _imageCache[shortName];
+      }
+    }
+    
+    // Kein Match - zeige gecachte Namen zum Debuggen
+    if (_imageCache.isNotEmpty) {
+      final similarKeys = _imageCache.keys.where((key) => 
+        key.toLowerCase().contains(cleanedName.toLowerCase().split(' ').first.toLowerCase()) ||
+        cleanedName.toLowerCase().contains(key.toLowerCase().split(' ').first.toLowerCase())
+      ).toList();
+      
+      if (similarKeys.isNotEmpty) {
+        print('  ⚠ No exact match for "$title" (cleaned: "$cleanedName"), but found similar cached: ${similarKeys.join(", ")}');
+      }
+    }
+    
+    return null;
+  }
