+                    
+                    if (period != null) {
+                      // AM/PM Format
+                      if (period == 'pm' && hour != 12) {
+                        hour += 12;
+                      } else if (period == 'am' && hour == 12) {
+                        hour = 0;
+                      }
+                    }
+                    
+                    releaseTime = DateTime(dayDate.year, dayDate.month, dayDate.day, hour, minute);
+                  }
+                }
+                
+                // Release hinzufügen
