+      // Versuche zuerst mit dem bereinigten Namen
+      var imageUrl = await _queryKitsu(searchName);
+      if (imageUrl.isNotEmpty) {
+        // Speichere im Cache
+        _imageCache[searchName] = imageUrl;
+        return imageUrl;
