+      
+      // Fallback: Wenn mehr als 3 Wörter, versuche nur die ersten 3
+      final words = searchName.split(' ');
+      if (words.length > 3) {
+        final shortName = words.take(3).join(' ');
+        imageUrl = await _queryKitsu(shortName);
