+      }
+      
+      final cachedJson = prefs.getString(cacheKey);
+      if (cachedJson != null) {
+        final List<dynamic> jsonList = json.decode(cachedJson);
+        final releases = jsonList.map((item) => AnimeRelease.fromJson(item)).toList();
