+          await _saveMonthToCache(dateInMonth, releases);
+          // Benachrichtige UI
+          onImageLoaded?.call();
+        }
+        
+        return releases;
+      }
+    } catch (e) {
+      print('Error loading month from cache: $e');
+    }
+    return [];
