+      if (imageUrl.isNotEmpty) {
+        // Speichere im Cache
+        _imageCache[searchName] = imageUrl;
+        return imageUrl;
+      }
+      
+      // Spezialfall: Entferne einzelne Buchstaben wie "x" (z.B. "SPY x FAMILY" -> "SPY FAMILY")
