+            print('✓ Found description from Kitsu: ${synopsis.substring(0, synopsis.length > 50 ? 50 : synopsis.length)}...');
+            return release.description!;
+          }
+        }
+      }
+      
+      // Fallback: Versuche mit kürzerem Namen
+      final words = searchName.split(' ');
