+    try {
+      final prefs = await SharedPreferences.getInstance();
+      final cacheKey = _getMonthCacheKey(dateInMonth);
+      
+      // Lade Image-Cache falls noch nicht im Speicher
+      if (_imageCache.isEmpty) {
