+      // Fallback: Versuche nur die ersten 2 Wörter
+      if (words.length > 2) {
+        final shortName = words.take(2).join(' ');
+        imageUrl = await _queryKitsu(shortName);
+        if (imageUrl.isNotEmpty) {
+          _imageCache[searchName] = imageUrl;
