+  /// Wendet gecachte Bild-URLs auf die Releases an
+  void _applyCachedImagesToReleases(List<AnimeRelease> releases, {bool notifyUI = false}) {
+    print('🔍 Applying cached images to ${releases.length} releases (imageCache has ${_imageCache.length} entries)');
+    
+    var appliedCount = 0;
+    var notFoundCount = 0;
+    var alreadyHaveCount = 0;
+    
+    for (var release in releases) {
+      if ((release.imageUrl == null || release.imageUrl!.isEmpty)) {
+        // Suche im Image-Cache nach einer passenden URL
+        final cachedUrl = _findCachedImageUrl(release.title);
+        if (cachedUrl != null && cachedUrl.isNotEmpty) {
+          release.imageUrl = cachedUrl;
+          appliedCount++;
+        } else {
+          notFoundCount++;
+        }
+      } else {
+        alreadyHaveCount++;
+      }
+    }
+    
+    print('📊 Results: $appliedCount applied, $alreadyHaveCount already had, $notFoundCount not found');
+    
+    if (appliedCount > 0) {
+      print('✓ Applied $appliedCount cached image URLs to releases');
+      // Benachrichtige UI dass Bilder aus Cache angewendet wurden
+      if (notifyUI) {
+        onImageLoaded?.call();
+      }
+    }
+    if (notFoundCount > 0) {
+      print('⚠ $notFoundCount releases still need image URLs');
+    }
+  }
