+    
+    // Signalisiere Ende des Ladens
+    onImageLoadingChanged?.call(false, total, total);
+    
+    // Speichere aktualisierten Cache inkl. verarbeitete Titel
+    if (total > 0) {
+      await _saveToCache(releases);
+    }
+  }
