+  DateTime _getMonthsAgo(int months) {
+    int year = DateTime.now().year;
+    int month = DateTime.now().month - months;
+    while (month <= 0) {
+      year--;
+      month += 12;
+    }
+    return DateTime(year, month, 2); // Tag 2 statt 1 für Grenzfall-Handling
+  }
