-      
-      // Kleine Pause um Kitsu API nicht zu überlasten
-      await Future.delayed(const Duration(milliseconds: 100));
-    }
-    
-    // Signalisiere Ende des Ladens
-    onImageLoadingChanged?.call(false, total, total);
