+  Future<bool> _isCacheValid() async {
+    // Lade immer zuerst aus SharedPreferences, falls im Speicher leer
+    if (_cachedReleases.isEmpty || _lastUpdate == null || _imageCache.isEmpty) {
+      await _loadFromCache();
+    }
+    
+    // Kein Cache vorhanden
+    if (_cachedReleases.isEmpty || _lastUpdate == null) {
+      if (_debugPrint) print('No cache available');
+      return false;
+    }
+    
+    final timeSinceUpdate = DateTime.now().difference(_lastUpdate!);
+    final isValid = timeSinceUpdate < _updateInterval;
+    if (_debugPrint) print('Cache age: ${timeSinceUpdate.inMinutes} minutes, valid: $isValid');
+    return isValid;
+  }
