-    }
-    
-    // Versuche erste 2 Wörter
-    if (words.length > 2) {
-      final shortName = words.take(2).join(' ').toLowerCase();
-      for (final entry in _imageCache.entries) {
-        if (entry.key.toLowerCase() == shortName && entry.value.isNotEmpty) {
