import 'dart:convert';
import 'package:http/http.dart' as http;
import 'package:html/parser.dart' as html_parser;
import 'package:html/dom.dart';
import '../models/anime_release.dart';

class CrunchyrollService {
  static const String baseUrl = 'https://www.crunchyroll.com';
  
  // Da Web-Scraping von Crunchyroll komplex ist und oft blockiert wird,
  // verwenden wir Beispieldaten. In einer Produktionsapp würde man die offizielle API nutzen
  // oder einen Backend-Service aufbauen
  
  Future<List<AnimeRelease>> getReleasesForWeek(DateTime startDate) async {
    // Beispiel-Daten für die Demo
    return _getMockData(startDate);
  }

  Future<List<AnimeRelease>> getReleasesForDay(DateTime date) async {
    final weekData = await getReleasesForWeek(date);
    return weekData.where((release) {
      return release.releaseTime.year == date.year &&
          release.releaseTime.month == date.month &&
          release.releaseTime.day == date.day;
    }).toList();
  }

  // Mock-Daten basierend auf typischen Crunchyroll-Releases
  List<AnimeRelease> _getMockData(DateTime startDate) {
    final List<AnimeRelease> releases = [];
    final random = DateTime.now().millisecond;
    
    // Beliebte Anime mit typischen Release-Zeiten
    final animeShows = [
      {'title': 'JUJUTSU KAISEN', 'image': 'https://www.crunchyroll.com/imgsrv/display/thumbnail/1200x675/catalog/crunchyroll/6ed1015ab0e75b42692c8c6988e1c0e5.jpg'},
      {'title': 'Frieren – Nach dem Ende der Reise', 'image': 'https://www.crunchyroll.com/imgsrv/display/thumbnail/1200x675/catalog/crunchyroll/87759366311f7f474ceb029694491029.jpg'},
      {'title': 'My Hero Academia: Vigilantes', 'image': 'https://www.crunchyroll.com/imgsrv/display/thumbnail/1200x675/catalog/crunchyroll/c27bfc8c8c3d9a7fc6f0e1f8c8b85a5e.jpg'},
      {'title': 'THE HOLY GRAIL OF ERIS', 'image': 'https://www.crunchyroll.com/imgsrv/display/thumbnail/1200x675/catalog/crunchyroll/8a82c2d5eb8f4c8fb4f0c9b6f3e7d0a1.jpg'},
      {'title': 'Roll Over and Die', 'image': 'https://www.crunchyroll.com/imgsrv/display/thumbnail/1200x675/catalog/crunchyroll/9b93d3e6fc9f5d9gc5g1d0c7g4f8e1b2.jpg'},
      {'title': 'The Invisible Man and His Soon-To-Be Wife', 'image': 'https://www.crunchyroll.com/imgsrv/display/thumbnail/1200x675/catalog/crunchyroll/0c04e4f7gd0g6e0hd6h2e1d8h5g9f2c3.jpg'},
      {'title': 'DARK MOON: THE BLOOD ALTAR', 'image': 'https://www.crunchyroll.com/imgsrv/display/thumbnail/1200x675/catalog/crunchyroll/1d15f5g8he1h7f1ie7i3f2e9i6h0g3d4.jpg'},
      {'title': 'Champignon Witch', 'image': 'https://www.crunchyroll.com/imgsrv/display/thumbnail/1200x675/catalog/crunchyroll/2e26g6h9if2i8g2jf8j4g3f0j7i1h4e5.jpg'},
      {'title': 'A Misanthrope Teaches a Class for Demi-Humans', 'image': 'https://www.crunchyroll.com/imgsrv/display/thumbnail/1200x675/catalog/crunchyroll/3f37h7i0jg3j9h3kg9k5h4g1k8j2i5f6.jpg'},
      {'title': 'OSHI NO KO', 'image': 'https://www.crunchyroll.com/imgsrv/display/thumbnail/1200x675/catalog/crunchyroll/4g48i8j1kh4k0i4lh0l6i5h2l9k3j6g7.jpg'},
    ];

    // Generiere Releases für die nächsten 7 Tage
    for (int dayOffset = 0; dayOffset < 7; dayOffset++) {
      final currentDay = startDate.add(Duration(days: dayOffset));
      
      // 3-5 Releases pro Tag
      final releasesPerDay = 3 + (dayOffset % 3);
      
      for (int i = 0; i < releasesPerDay; i++) {
        final anime = animeShows[(dayOffset * 3 + i) % animeShows.length];
        final hour = 14 + (i * 2); // Releases zwischen 14:00 und 20:00
        final episode = 1 + dayOffset + i;
        
        releases.add(
          AnimeRelease(
            title: anime['title']!,
            episodeNumber: episode.toString(),
            episodeTitle: 'Episode $episode',
            releaseTime: DateTime(
              currentDay.year,
              currentDay.month,
              currentDay.day,
              hour,
              (i * 15) % 60,
            ),
            imageUrl: anime['image'],
            seriesUrl: '$baseUrl/de/series/example',
            episodeUrl: '$baseUrl/de/watch/example',
            isPremiere: i == 0 && dayOffset == 0,
          ),
        );
      }
    }

    releases.sort((a, b) => a.releaseTime.compareTo(b.releaseTime));
    return releases;
  }

